    auto old=project;auto undo=undoStack,redo=redoStack;auto file=currentFile;auto rev=revision;auto wasDirty=dirty;auto track=selectedTrack;
    perform(stop);cancelNoteTool();project=emptyProject();project.songMode=true;project.bpm=120;project.loop=false;selectedTrack=5;project.patterns[0].length=4;project.patterns[0].lanes[5]={{0,1,60},{2,1,67}};Clip c;c.track=5;c.length=4;project.clips={c};currentFile={};publish();undoStack.clear();redoStack.clear();auto original=JSON::toString(projectToJson(project));
